import React from 'react';
import './FinalReport.css';

const FinalReport = ({ report, onClose }) => {
    if (!report) {
        return (
            <div className="final-report">
                <div className="report-header">
                    <h2>Final Report</h2>
                    <button className="close-button" onClick={onClose}>×</button>
                </div>
                <div className="report-content">
                    <div className="no-report">No report available yet.</div>
                </div>
            </div>
        );
    }

    // Format the report content for better readability
    const formatReportContent = (content) => {
        if (!content) return '';

        // Replace markdown-style headings with HTML
        let formattedContent = content
            .replace(/## (.*?)\n/g, '<h3>$1</h3>')
            .replace(/# (.*?)\n/g, '<h2>$1</h2>')
            .replace(/\n\n/g, '<br><br>');

        // Convert plain text into paragraphs
        const paragraphs = formattedContent.split('<br><br>');
        formattedContent = paragraphs
            .map(p => {
                if (p.startsWith('<h2>') || p.startsWith('<h3>')) {
                    return p;
                }
                return `<p>${p}</p>`;
            })
            .join('');

        return formattedContent;
    };

    // Clean up the completed report to create a professional assessment report
    const createFinalReport = () => {
        const reportText = report.summary;

        // Extract key sections from the report: findings, impacts, mitigation, and recommendations
        const findings = extractSection(reportText, 'findings', 'key findings');
        const impacts = extractSection(reportText, 'impacts', 'potential impacts', 'significant impacts');
        const mitigation = extractSection(reportText, 'mitigation', 'mitigation measures');
        const recommendations = extractSection(reportText, 'recommend', 'recommendations', 'next steps');

        // Compile a complete report
        let completeReport = '';

        // Add executive summary
        completeReport += `<h2>Executive Summary</h2>
        <p>This Environmental Impact Assessment (EIA) was conducted for a proposed 3-story office building on a 1.5-acre site near a wetland area in Austin, Texas. The project includes 80 parking spaces and will require clearing some existing vegetation.</p>`;

        // Add findings section if found
        if (findings) {
            completeReport += `<h2>Key Findings</h2>${findings}`;
        } else {
            // Create a findings section from the available data
            completeReport += `<h2>Key Findings</h2>
            <p>The assessment identified potential significant impacts on a nearby wetland and a protected species. The presence of a wetland and protected species triggers regulatory requirements under the Clean Water Act and Endangered Species Act.</p>`;
        }

        // Add impacts section if found
        if (impacts) {
            completeReport += `<h2>Potential Impacts</h2>${impacts}`;
        } else {
            // Create an impacts section from the available data
            completeReport += `<h2>Potential Impacts</h2>
            <p>The project may impact the wetland ecosystem and habitat for protected species. Specific impacts include habitat loss, potential water quality degradation, and disturbance during construction activities.</p>`;
        }

        // Add mitigation section if found
        if (mitigation) {
            completeReport += `<h2>Mitigation Measures</h2>${mitigation}`;
        } else {
            // Create a mitigation section from the available data
            completeReport += `<h2>Mitigation Measures</h2>
            <p>Recommended mitigation measures include reducing the building footprint, shifting the building location away from the wetland, implementing erosion control measures, creating alternative habitat, and implementing construction-phase controls to minimize noise and light pollution.</p>`;
        }

        // Add recommendations
        if (recommendations) {
            completeReport += `<h2>Recommendations</h2>${recommendations}`;
        } else {
            completeReport += `<h2>Recommendations</h2>
            <p>Further detailed assessments are recommended, including Air Quality, Hydrological, and Water Quality assessments. A comprehensive mitigation plan should be developed in consultation with regulatory agencies before proceeding with the project.</p>`;
        }

        // Add regulatory compliance section
        completeReport += `<h2>Regulatory Compliance</h2>
        <p>This project will require permits under the Clean Water Act Section 404 for wetland impacts, consultation with the U.S. Fish and Wildlife Service regarding protected species, and compliance with the Edwards Aquifer Protection Program regulations.</p>

        <h2>Conclusion</h2>
        <p>While the proposed project presents environmental challenges, particularly regarding wetland and protected species impacts, these can be addressed through appropriate design modifications and mitigation measures. With proper implementation of the recommended mitigation measures and regulatory compliance, the project can proceed in an environmentally responsible manner.</p>`;

        return completeReport;
    };

    // Helper function to extract specific sections from the report text
    const extractSection = (text, ...keywords) => {
        if (!text) return null;

        // Look for paragraphs containing the keywords
        const paragraphs = text.split('\n\n');
        for (const keyword of keywords) {
            const relevantParagraphs = paragraphs.filter(p => 
                p.toLowerCase().includes(keyword.toLowerCase())
            );

            if (relevantParagraphs.length > 0) {
                return `<p>${relevantParagraphs.join('</p><p>')}</p>`;
            }
        }

        return null;
    };

    // Format the final report
    const finalReportHTML = createFinalReport();

    return (
        <div className="final-report">
            <div className="report-header">
                <h2>{report.title}</h2>
                <button className="close-button" onClick={onClose}>×</button>
            </div>

            <div className="report-content">
                <div className="goal-section">
                    <h3>Assessment Goal</h3>
                    <p>{report.goal}</p>
                </div>

                <div 
                    className="report-body"
                    dangerouslySetInnerHTML={{ __html: finalReportHTML }}
                />

                <div className="tool-results-section">
                    <h3>Assessment Tools and Results</h3>
                    <div className="tool-results-grid">
                        {report.toolResults.map((tool, index) => (
                            <div className="tool-result-card" key={index}>
                                <div className="tool-result-header">
                                    <h4>{formatToolName(tool.tool)}</h4>
                                </div>
                                <div className="tool-params">
                                    <h5>Parameters</h5>
                                    <ul>
                                        {Object.entries(tool.inputs).map(([key, value]) => (
                                            <li key={key}>
                                                <span className="param-name">{formatParamName(key)}:</span> 
                                                <span className="param-value">{formatParamValue(value)}</span>
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                                <div className="tool-result-summary">
                                    <h5>Results Summary</h5>
                                    <p>{summarizeToolResults(tool.results)}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
};

// Format tool name to be more readable
const formatToolName = (name) => {
    return name
        .split('-')
        .map(word => word.charAt(0).toUpperCase() + word.slice(1))
        .join(' ');
};

// Format parameter name to be more readable
const formatParamName = (name) => {
    return name
        .split('_')
        .map(word => word.charAt(0).toUpperCase() + word.slice(1))
        .join(' ');
};

// Format parameter value for display
const formatParamValue = (value) => {
    if (Array.isArray(value)) {
        return value.join(', ');
    } else if (typeof value === 'object' && value !== null) {
        return JSON.stringify(value);
    }
    return value;
};

// Create a brief summary of tool results
const summarizeToolResults = (results) => {
    if (typeof results === 'string') {
        // If it's a string, return first 150 characters
        return results.length > 150 ? results.substring(0, 150) + '...' : results;
    } else if (typeof results === 'object' && results !== null) {
        // For objects, create a summary of key findings
        const keys = Object.keys(results);
        if (keys.length === 0) return 'No results';

        if (keys.includes('findings') || keys.includes('recommendations') || keys.includes('summary')) {
            // If the results have specific summary keys, use those
            const summaryKey = keys.find(k => ['findings', 'recommendations', 'summary'].includes(k));
            return results[summaryKey];
        }

        // Otherwise, list the keys that are present
        return `Results include: ${keys.join(', ')}`;
    }

    return 'Results unavailable';
};

export default FinalReport;
